-- Madvert Operations · Client Onboarding schema (Postgres).
-- The app creates these tables automatically on first use (src/onboarding/server/db.ts).
-- Run this file manually only if your database user cannot create tables.
-- Each model is one table; the typed record is stored in `data` (see src/onboarding/types.ts).

create table if not exists onb_clients (id text primary key, onboarding_id text, data jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists onb_clients_onboarding_idx on onb_clients (onboarding_id);
create index if not exists onb_clients_data_idx on onb_clients using gin (data jsonb_path_ops);
